from pathlib import Path
import json

p=Path(__file__).parent/'2026.10.12 Contract PECH continut.json'
d=json.loads(p.read_text(encoding='utf-8'))
def s(prefix):return next(x for x in d['sections']if x['title'].startswith(prefix))

x=s('§ 5')
x['paragraphs'][0]='(1) Der AN übernimmt im Rahmen der unveränderten Position 05 ausdrücklich auch die vertraglichen Prüfingenieurleistungen nach §§ 127 und 128 BO für Wien für dieses Vorhaben. Der konkrete Prüfingenieur muss als befugter Ziviltechniker oder als gerichtlich beeideter Sachverständiger für das einschlägige Fachgebiet die gesetzlichen Voraussetzungen erfüllen. Seine Stellvertretung, Funktion und Befugnis werden vor Bestellung in Anlage 4 dokumentiert. Die AG nimmt die erforderliche Bestellung beziehungsweise Bekanntgabe unter Verwendung der vom AN vorbereiteten Unterlagen vor. Eine bereits erfolgte Bestellung wird durch diesen ununterzeichneten Entwurf nicht behauptet.'
x['paragraphs'][5]='(6) Der AN erstellt die für seinen Fachbereich erforderlichen Befunde und Bestätigungen zur Fertigstellungsanzeige nach § 128 BO für Wien, stellt das tragwerksbezogene Nachweispaket vollständig zusammen und wirkt an einer erforderlichen fachübergreifenden Ziviltechnikerbestätigung mit. Die gesetzlich erforderliche Bestätigung nach § 128 Abs. 2 Z 1 ist von einem dafür befugten Ziviltechniker mit aufrechter Befugnis zu erstellen; eine bloße Sachverständigenbestellung als Prüfingenieur ersetzt diese gesonderte Voraussetzung nicht. Übernimmt der benannte befugte Ziviltechniker die umfassende Bestätigung, werden alle notwendigen Fremdbefunde vorher geprüft und dokumentiert. Er darf weder fachfremde Sachverhalte ohne ausreichende Grundlage bestätigen noch erforderliche eigene tragwerksbezogene Schlussnachweise unter Verweis auf Dritte auslassen. Der AN organisiert die erforderliche geeignete bestätigende Person innerhalb der vereinbarten Gesamtpauschale.'
x=s('§ 8')
x['paragraphs'][1]='(1a) Die für Bauwerksbucherstellung und gesetzliche Erstprüfung benannten Personen müssen jeweils nach § 128a BO für Wien in der maßgeblichen Fassung befugt sein. Die dort erforderliche Unabhängigkeit von Bauwerber, Bauführer und Eigentümer sowie von relevanten Dienst- und Organschaftsverhältnissen wird vor Übernahme der jeweiligen Funktion schriftlich nachgewiesen. Der AN benennt sowohl die erstellende als auch die zur Erstprüfung verantwortliche Person und dokumentiert die gesetzlich zulässige personelle Gestaltung. Eine interne Qualitätssicherung ersetzt keine gesetzlichen Befugnis- oder Unabhängigkeitsvoraussetzungen. Erforderliche geeignete unabhängige Personen werden innerhalb der vereinbarten Gesamtpauschale organisiert.'
x['paragraphs'][2]='(2) Das Bauwerksbuch enthält die gesetzlich erforderlichen und zusätzlich vereinbarten Inhalte: Gebäudedaten, Eigentümer- und Objektzuordnung, bewilligte und relevante historische Planstände, vorhandene Bewilligungen und relevante Unterlagen nach § 118c BO für Wien, Beschreibung des bestehenden und neuen Tragwerks, verwendete Grundlagen, erforderliche Erstprüfung mit Datum und unterzeichnetem Befund, Zustands- und Fotodokumentation mit statisch relevanten Rissen und Schäden, festgestellte Mängel mit Priorität, Behebungsmaßnahmen und Fristen, Termin und Umfang der nächsten Prüfung, regelmäßige Prüf- und Instandhaltungsintervalle, Verantwortlichkeiten, praktische Prüfhinweise sowie nachvollziehbare Dokumenten- und Planverweise mit Ablageorten.'
x['paragraphs'][2]=x['paragraphs'][2].replace('vorhandene Bewilligungen und relevante Unterlagen nach § 118c BO für Wien', 'vorhandene Bewilligungen und die gesetzlich erforderliche Dokumentation einschlägiger Änderungen beziehungsweise Maßnahmen')
x['paragraphs'].append('(2a) Der AN übernimmt in das Bauwerksbuch die nach § 128a Abs. 4 Z 7 erforderliche Dokumentation der einschlägigen Maßnahmen und Änderungen gemäß § 118c Abs. 2 und 7. Die AG und zuständigen Energie- beziehungsweise Haustechnikfachplaner liefern die fachfremden Nachweise; der AN fordert sie konkret an, ordnet sie zu und dokumentiert fehlende Grundlagen. Energetische Systemplanung oder Ausführung solcher Maßnahmen werden dadurch nicht beauftragt; tragwerksbezogene Schnittstellen bleiben geschuldet.')
x['paragraphs'].append('(8) Die Bewertung, Dokumentation und Erstellung eines nachvollziehbaren Mängelbehebungsplans für vorhandene Gebäudedefekte sind Teil des Bauwerksbuchauftrags. Eine körperliche Reparatur oder Sanierung historischer Schäden durch den AN wird damit nicht beauftragt; sie ist von der AG durch geeignete Ausführende zu veranlassen. Der AN bezeichnet notwendige Maßnahmen und sichere Fristen und erfüllt einschlägige Warn- und Meldepflichten. Das vollständige Bauwerksbuch wird elektronisch als unterzeichnetes PDF und in einem im vereinbarten Zweck bearbeitbaren Format mit verknüpfter Dokumentenstruktur übergeben; ein gegebenenfalls gesetzlich erforderliches Format hat Vorrang.')
x=s('§ 12')
x['paragraphs'][4]="(5) Als ausdrücklicher neuer AG-Verhandlungsvorschlag wird abweichend von 'Kein Haftrücklass' ein Haftrücklass von 5% des jeweils freigegebenen Netto-Rechnungsbetrags vereinbart. Er sichert vertragliche Erfüllungs- und Mängelbehebungsansprüche. Die vertragliche Gewährleistungsfrist beträgt mindestens drei Jahre ab vollständiger dokumentierter Abnahme des Gesamtpakets; längere gesetzliche Fristen und eigenständige Schadenersatzansprüche bleiben unberührt. Dies ist eine neue vertragliche Vereinbarung und keine Aussage, dass gesetzlich für jede einzelne Leistung zwingend ein einheitlicher Dreijahreszeitraum gilt. Nach Ablauf der vereinbarten Frist wird der Haftrücklass freigegeben, ausgenommen ein angemessener Teil für konkret geltend gemachte, noch offene gesicherte Ansprüche. Der AN kann ihn durch eine gleichwertige in Österreich durchsetzbare Bankgarantie mit gleichem Betrag, Sicherungszweck und angemessener Laufzeit ersetzen. Das Garantieformular wird vor Unterzeichnung gemeinsam vereinbart. Zwingende Rechte des AN nach § 1170b ABGB bleiben unberührt."
x=s('§ 14')
x['paragraphs'][1]='(2) Übernahme, Vollständigkeitsfreigabe oder Zahlung einer Teilrechnung sind weder Verzicht auf Gewährleistungs- und Schadenersatzansprüche noch Entlastung von fachlicher Verantwortung. Die vertragliche Gewährleistungsfrist beträgt mindestens drei Jahre ab vollständiger dokumentierter Abnahme des Gesamtpakets gemäß § 12; längere gesetzliche Fristen und eigenständige Schadenersatzansprüche bleiben unberührt. Gesetzliche Mängelrechte auf Behebung, Preisminderung oder Vertragsauflösung werden nicht verkürzt. Verdeckte Mängel werden nach Entdeckung mitgeteilt; die Rechnungsreklamationsfrist bewirkt keinen Mängelverzicht.'
x=s('§ 17')
x['paragraphs'][3]='(4) Zusätzlich kann die AG den noch unerbrachten Teil jederzeit schriftlich abberufen beziehungsweise vorzeitig beenden. Die Vergütungsfolgen einer Abberufung aus der Sphäre der AG richten sich nach § 1168 ABGB in der anwendbaren Fassung. Bei Vorliegen dessen Voraussetzungen kann dem leistungsbereiten AN das vereinbarte Entgelt zustehen; anzurechnen sind die infolge Unterbleibens ersparten Aufwendungen, das durch anderweitige Verwendung Erworbene sowie das absichtlich zu erwerben Versäumte. Eine automatische Begrenzung allein auf physisch bereits geleistete Arbeit oder ein stets kostenfreier Abbruch wird nicht vereinbart. Der AN legt die geltend gemachte Restvergütung und die anzurechnenden Beträge nachvollziehbar offen; Originalpauschalen, tatsächlich erfüllte Teile, ersparte Leistungen, anderweitige Auslastung, freigegebene Fremdkosten und bereits bezahlte Beträge werden transparent abgeglichen. Ansprüche und Gegenansprüche infolge einer schuldhaften Vertragsverletzung sind getrennt zu beurteilen; doppelte Vergütung ist ausgeschlossen.'
x=s('§ 18')
x['paragraphs'][2]='(3) Die deutsche Vertragsfassung ist für den beiderseitigen Vertragsinhalt maßgeblich. Die rumänische Lesesynthese erläutert den Entwurf und seine Verhandlungspunkte; sie ist keine abweichende Leistungsbeschreibung. Individualvereinbarungen gehen allgemeinen Bedingungen vor.'
x=s('Anlage 1B')
for r in x['table']['rows']:
    if r[0]=='Zahlung':r[2]='30 Tage/prüffähige Lieferung; keine ungedeckte Vorauszahlung; 5% Haftrücklass bis zum Ende der mindestens dreijährigen vertraglichen Gewährleistungsfrist; Bankgarantie möglich.'
    if r[0]=='Beendigung':r[2]='Wichtiger Grund und AG-Abberufung; nachvollziehbare Abrechnung nach § 1168 einschließlich ersparter Aufwendungen und anderweitigen Erwerbs; Nachfolgerübergabe.'
for v in d['open_fields']:
    if v['field']=='Bauwerksbuch-Personen':v['value']='Autor und Erstprüfer nach § 128a; Befugnis und Unabhängigkeit von Bauwerber/Bauführer/Eigentümer; Umfang, Erstprüfung, nächste Prüfung, Mängelbehebungsplan und genaue Frist/Meldepflicht.'
    if v['field']=='Prüfingenieur/Prüfperson':v['value']='Gesetzlich geeigneter Ziviltechniker oder gerichtlicher Sachverständiger, Unabhängigkeit und Bestellunterlagen; gesondert befugter Ziviltechniker für § 128 Bestätigung.'
s('Anlage 4')['table']['rows']=[[v['field'],v['value'],v['deadline']]for v in d['open_fields']]
d['summary_ro'][5]='Se negociază preț fix fără index ZT, plată în 30 de zile după livrare verificabilă, retenție de 5% din facturile nete și garanție contractuală de minimum 3 ani după recepția integrală, cu posibilitatea unei garanții bancare echivalente. Acestea modifică expres regula PECH „Kein Haftrücklass”. Se adaugă drepturi de utilizare/modificare/terți, fișiere editabile, asigurare, răspundere și suplimente numai aprobate. Încetarea implică decont conform § 1168: poate exista remunerație și pentru partea neexecutată, cu deducerea economiilor și veniturilor alternative prevăzute de lege. Drepturile imperative, inclusiv eventuala garanție de plată § 1170b ABGB, sunt păstrate.'
d['audit_notes']=['Proiect AG. Cifre și condiții originale verificate; conținutul juridic supus auditului separat înaintea redării finale.','§§ 127, 128 și 128a BO für Wien în forma aplicabilă după 2026.07.15; §§ 1168 și 1170b ABGB; confirmarea în concret a persoanelor, termenelor și registrării rămâne necesară.']
p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
print(p)
